package com.bedlessfighter.necroManager.commands;
import com.bedlessfighter.necroManager.managers.MessageManager;import com.bedlessfighter.necroManager.managers.ConfigManager;import org.bukkit.command.*;import org.jetbrains.annotations.NotNull;
public final class RulesCommand implements CommandExecutor {public boolean onCommand(@NotNull CommandSender s, @NotNull Command c, @NotNull String label, @NotNull String @NotNull [] a){if(a.length!=0){MessageManager.sendRaw(s,MessageManager.prefix()+" &cUsage: /rules");return true;}MessageManager.sendRaw(s,MessageManager.color(MessageManager.configured("messages.rules-header","&6&lServer Rules")));for(String line:ConfigManager.getStringList("rules",java.util.List.of("&71. Be respectful.","&72. No cheating.","&73. Follow staff instructions.")))MessageManager.sendRaw(s,MessageManager.color(line));return true;}}